587	// checkCampaignClaimWindow 核对每个已领取的下载/安装/回滚操作的首次领取时间
588	// 都落在活动保存的原维护窗口 [start, end) 内：开始时刻包含、结束时刻不包含。
589	// 首次领取必须遵守维护窗口——早于开始或恰好到达、晚于结束的领取记录都使整个
590	// 存储损坏，即使其余状态与结果历史完全自洽、活动仍在执行或已成功/失败结束、
591	// 该操作后来成功、失败或超时，也不能把窗口外的首次领取当作有效进度接受，
592	// 更不能通过挪动领取时间、撤销领取、删去活动或重写进度来消除矛盾。
593	// 这项核对只针对真正首次领取的时刻：尚未领取的操作没有领取时间（等待下载、
594	// 等待安装、等待回滚及未领取便结束的记录），属正常缺省，不参与核对；未开启
595	// 回滚的活动内存中只有缺省的回滚操作标识，不算已领取。已经在窗口内领取的
596	// 操作，后来在窗口外的重复查询、截止前的结果接受以及活动结束时间都不要求
597	// 重新满足窗口。比较按绝对时刻进行，时区写法不同不视为矛盾。
598	func checkCampaignClaimWindow(campaignID string, c *campaignState) error {
599		for _, cd := range c.Devices {
600			ops := []struct {
601				stage string
602				op    *opState
603			}{
604				{StageDownload, &cd.Download},
605				{StageInstall, &cd.Install},
606				{StageRollback, &cd.Rollback},
607			}
608			for _, item := range ops {
609				if !item.op.Claimed {
610					continue
611				}
612				at := item.op.ClaimedAt
613				// 窗口为 [start, end)：恰好到达开始合法，恰好到达结束不合法。
614				// time.Time 的比较按绝对时刻进行，同一时刻的不同时区写法结果相同。
615				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
616					return fmt.Errorf("%w: campaign %s device %s %s first claimed at %s outside maintenance window [%s, %s)",
617						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
618						at.Format(time.RFC3339Nano),
619						c.WindowStart.Format(time.RFC3339Nano),
620						c.WindowEnd.Format(time.RFC3339Nano))
621				}
622			}
623		}
624		return nil
625	}
