627	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
628	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
629	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
630	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
631	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
632	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
633	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
634		baseline := c.LastTime
635		bad := func(format string, args ...any) error {
636			msg := fmt.Sprintf(format, args...)
637			return fmt.Errorf("%w: campaign %s time baseline %s %s",
638				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
639		}
640		if baseline.Before(c.CreatedAt) {
641			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
642		}
643		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
644			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
645		}
646		for _, cd := range c.Devices {
647			if !cd.At.IsZero() && baseline.Before(cd.At) {
648				return bad("before device %s state time %s",
649					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
650			}
651			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
652			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
653			// 的操作对应时间为零值，属正常缺省，跳过比较。
654			ops := []struct {
655				stage string
656				op    *opState
657			}{
658				{StageDownload, &cd.Download},
659				{StageInstall, &cd.Install},
660				{StageRollback, &cd.Rollback},
661			}
662			for _, item := range ops {
663				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
664					return bad("before device %s %s claim time %s",
665						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
666				}
667				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
668					return bad("before device %s %s result time %s",
669						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
670				}
671			}
672		}
673		return nil
674	}
675	
676	// checkCampaignResultOrder 校验每个已经接受结果的下载/安装/回滚操作，其首次
677	// 结果发生时间都不早于该操作自己的首次领取时间：同一活动、同一设备、同一阶段
678	// 的两个时刻直接比较，成功与失败适用同一规则。结果先于领取在因果上不可能，
679	// 必须使整个存储拒绝打开；不能用其他设备的领取时间、设备影子的最近上报时间、
680	// 活动的最新时间或结束时间替代这两个时刻，也不能通过修改时间、删除结果历史、
681	// 撤销领取或改变设备状态让记录变得合法。后来安装成功或回滚完成同样不能掩盖
682	// 早先阶段的矛盾，因此该核对对仍在执行和已结束的活动都生效。
683	// 只比较该操作自己确实存在的两个时刻：尚未接受结果（含已领取未完成、随后因
684	// 截止超时）的操作没有结果时间，尚未领取的等待步骤没有领取时间，均属正常
685	// 缺省，跳过核对。首次领取时因版本不兼容而直接形成的下载失败，领取与失败
686	// 可以是同一时刻；两时刻相等合法。已领取操作在窗口结束后、截止前提交结果
687	// 不受限制——本核对不要求结果落在维护窗口内。比较按绝对时刻进行，时区写法
688	// 不同不视为矛盾。重复提交不覆盖首次记录，这里使用的就是首次接受的两个时刻。
689	func checkCampaignResultOrder(campaignID string, c *campaignState) error {
690		for _, cd := range c.Devices {
691			ops := []struct {
692				stage string
693				op    *opState
694			}{
695				{StageDownload, &cd.Download},
696				{StageInstall, &cd.Install},
697				{StageRollback, &cd.Rollback},
698			}
699			for _, item := range ops {
700				o := item.op
701				// 未接受结果（含已领取未完成、超时）或未领取的操作不参与核对：
702				// HasResult 为 true 时上方的操作校验已保证 Claimed 且两个时间非零。
703				if !o.HasResult {
704					continue
705				}
706				// time.Time 的比较按绝对时刻进行：结果早于首次领取即损坏，
707				// 相同时刻的不同时区写法结果相同，相等合法。
708				if o.At.Before(o.ClaimedAt) {
709					return fmt.Errorf("%w: campaign %s device %s %s result at %s before first claim at %s",
710						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
711						o.At.Format(time.RFC3339Nano), o.ClaimedAt.Format(time.RFC3339Nano))
712				}
713			}
714		}
715		return nil
716	}
717	
718	// checkSuccessReport 核对一条已接受的安装/回滚成功记录保存的附带上报与
719	// 对应设备影子最近接受的上报之间的关系。序号必须是正整数且不大于设备最近
720	// 接受的序号：缺失、为零或大于设备记录都按损坏处理。两边序号相等时，这条
721	// 成功记录代表的就是设备最近一次上报，其版本、完整上报配置与首次接受结果时
722	// 保存的发生时间必须分别与影子保存的版本、上报配置和最近上报时间一致
723	// （配置按 JSON 语义比较，时间按同一时刻判断，不因时区表示不同而报错）。
724	// 序号更小则是已被后续上报覆盖的历史记录，不要求与当前影子一致。
725	// 设备当前是否在线不影响本核对；下载结果、失败结果与没有成功结果的阶段
726	// 不保存附带上报序号，也不进入本核对。
727	func checkSuccessReport(campaignID string, dd diskDev, o diskOp, stage string, d *deviceState) error {
728		bad := func(format string, args ...any) error {
729			msg := fmt.Sprintf(format, args...)
730			return fmt.Errorf("%w: campaign %s device %s %s success report %s",
731				ErrCorruptStorage, campaignID, dd.DeviceID, stage, msg)
732		}
733		if o.ResultSeq == 0 {
734			return bad("missing report sequence")
735		}
736		if o.ResultSeq > d.LastSeq {
737			return bad("sequence %d not accepted by device (last accepted %d)", o.ResultSeq, d.LastSeq)
738		}
739		if o.ResultSeq == d.LastSeq {
740			if o.ResultVersion != d.Version {
741				return bad("version %s does not match latest reported version %s", o.ResultVersion, d.Version)
742			}
743			if !rawEqual(o.ResultConfig, d.Reported) {
744				return bad("config does not match latest reported config")
745			}
746			if !o.At.Equal(d.LastReportTime) {
747				return bad("time %s does not match latest report time %s",
748					o.At.Format(time.RFC3339Nano), d.LastReportTime.Format(time.RFC3339Nano))
749			}
750		}
751		return nil
752	}
