754	func validDeviceStatus(status string) bool {
755		switch status {
756		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
757			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
758			DeviceAwaitingRollback, DeviceRollingBack,
759			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
760			return true
761		default:
762			return false
763		}
764	}
765	
766	// isRollbackTerminal 判断状态是否属于回滚相关终态。
767	func isRollbackTerminal(status string) bool {
768		switch status {
769		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
770			return true
771		default:
772			return false
773		}
774	}
775	
776	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
777	func isRollbackFlowStatus(status string) bool {
778		switch status {
779		case DeviceAwaitingRollback, DeviceRollingBack,
780			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
781			return true
782		default:
783			return false
784		}
785	}
