787	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
788	func validateRollbackDisk(campaignID string, dd diskDev) error {
789		bad := func(msg string) error {
790			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
791		}
792		rb := dd.Rollback
793		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
794		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
795		if dd.RollbackTarget != "" && !dd.Download.Claimed {
796			return bad("rollback target locked before download claim")
797		}
798		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
799		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
800		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
801		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
802		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
803		// 结果）允许没有目标：这种失败不进入安装或回滚。
804		if dd.RollbackTarget == "" && dd.Download.Claimed &&
805			(!dd.Download.HasResult || dd.Download.Success) {
806			return bad("missing locked rollback target")
807		}
808		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
809		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
810			return bad("rollback status without locked target")
811		}
812		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
813		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
814		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
815		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
816		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
817		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
818		// （这里只看本设备本活动保存的安装操作结果本身）。
819		installFailed := dd.Install.HasResult && !dd.Install.Success
820		if isRollbackFlowStatus(dd.Status) && !installFailed {
821			return bad("rollback state without accepted install failure")
822		}
823		switch dd.Status {
824		case DeviceAwaitingRollback:
825			// 已接受安装失败、回滚尚未领取：回滚无结果。
826			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
827				return bad("awaiting rollback state mismatch")
828			}
829		case DeviceRollingBack:
830			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
831				return bad("rolling back state mismatch")
832			}
833		case DeviceRollbackSucceeded:
834			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
835				return bad("rollback succeeded without success result")
836			}
837			if rb.ResultVersion != dd.RollbackTarget {
838				return bad("rollback version mismatch")
839			}
840			if _, ok := decodeObject(rb.ResultConfig); !ok {
841				return bad("rollback config invalid")
842			}
843		case DeviceRollbackFailed:
844			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
845				return bad("rollback failed without failure result")
846			}
847		case DeviceRollbackTimeout:
848			if dd.Phase != StageRollback {
849				return bad("rollback timeout phase mismatch")
850			}
851			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
852			if rb.HasResult {
853				return bad("rollback timeout with result")
854			}
855		default:
856			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
857			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
858			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
859			if dd.Install.HasResult && !dd.Install.Success {
860				return bad("install failure without rollback state")
861			}
862			if rb.Claimed || rb.HasResult {
863				return bad("rollback progressed without install failure")
864			}
865		}
866		return nil
867	}
868

