package shadow

import (
	"encoding/json"
	"testing"
	"time"
)

// deviceDoc 返回保存文件中某活动某设备的 JSON 节点，供改写损坏场景使用。
func deviceDoc(doc map[string]any, campID, devID string) map[string]any {
	for _, d := range campaignDoc(doc, campID)["devices"].([]any) {
		m := d.(map[string]any)
		if m["deviceId"] == devID {
			return m
		}
	}
	return nil
}

// setupDownloading 构造已领取下载、尚无下载结果的设备，关闭后返回存储目录。
func setupDownloading(t *testing.T) (*Store, string, CampaignSpec) {
	t.Helper()
	s := setupUpgrade(t, "d1")
	spec := upSpec()
	spec.Devices = []string{"d1"}
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")
	if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
		t.Fatalf("claim download: %v", err)
	}
	dir := s.dir
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	return s, dir, spec
}

// setupInstalling 构造下载成功、安装已领取但尚无安装结果的设备，
// 返回安装操作标识与关闭后的存储目录。
func setupInstalling(t *testing.T) (*Store, string, CampaignSpec, string) {
	t.Helper()
	s, dir, spec := setupReady(t)
	// setupReady 已关闭存储，重新打开后领取安装。
	s2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen ready: %v", err)
	}
	in, err := s2.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
	if err != nil {
		t.Fatalf("claim install: %v", err)
	}
	if in == nil || in.Kind != StageInstall {
		t.Fatalf("want install op, got %+v", in)
	}
	if err := s2.Close(); err != nil {
		t.Fatal(err)
	}
	return s2, dir, spec, in.ID
}

// TestInstallProgressRestoreCorrupt 针对等待安装（ready）与正在安装
// （installing）两种状态的恢复核对：保存的状态与本设备在该活动中已接受的
// 操作结果不符时，必须拒绝打开整个存储并原样保留文件。
func TestInstallProgressRestoreCorrupt(t *testing.T) {
	t.Run("ready but install already claimed", func(t *testing.T) {
		_, dir, _ := setupReady(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			dev := deviceDoc(doc, "cmp-1", "d1")
			dev["install"].(map[string]any)["claimed"] = true
			dev["install"].(map[string]any)["claimedAt"] = "2026-10-02T12:01:00Z"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("ready but wrong phase", func(t *testing.T) {
		_, dir, _ := setupReady(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["phase"] = "download"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("installing but install never claimed", func(t *testing.T) {
		_, dir, _ := setupReady(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["status"] = "installing"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("installing but wrong phase", func(t *testing.T) {
		_, dir, _ := setupReady(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			dev := deviceDoc(doc, "cmp-1", "d1")
			dev["status"] = "installing"
			dev["phase"] = "download"
			dev["install"].(map[string]any)["claimed"] = true
			dev["install"].(map[string]any)["claimedAt"] = "2026-10-02T12:01:00Z"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("install success recorded as ready", func(t *testing.T) {
		// 操作标识、时间与结果历史各自合法，也不能把已完成安装的设备
		// 解释成仍在等待安装。
		_, dir, _ := setupSucceeded(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["status"] = "ready"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("install success recorded as installing", func(t *testing.T) {
		_, dir, _ := setupSucceeded(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["status"] = "installing"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("install failure recorded as ready", func(t *testing.T) {
		_, dir, _, _ := setupInstallFailure(t, false)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["status"] = "ready"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("install failure recorded as installing", func(t *testing.T) {
		_, dir, _, _ := setupInstallFailure(t, false)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			deviceDoc(doc, "cmp-1", "d1")["status"] = "installing"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("ready without download success", func(t *testing.T) {
		_, dir, _ := setupDownloading(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			dev := deviceDoc(doc, "cmp-1", "d1")
			dev["status"] = "ready"
			dev["phase"] = "install"
		})
		assertReopenCorrupt(t, dir, original)
	})

	t.Run("installing without download success", func(t *testing.T) {
		_, dir, _ := setupDownloading(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			dev := deviceDoc(doc, "cmp-1", "d1")
			dev["status"] = "installing"
			dev["phase"] = "install"
			dev["install"].(map[string]any)["claimed"] = true
