package shadow

import (
	"encoding/json"
	"testing"
	"time"
)

// deviceDoc 返回保存文件中某活动某设备的 JSON 节点，供改写损坏场景使用。
func deviceDoc(doc map[string]any, campID, devID string) map[string]any {
	for _, d := range campaignDoc(doc, campID)["devices"].([]any) {
		m := d.(map[string]any)
		if m["deviceId"] == devID {
			return m
		}
	}
	return nil
}

// setupDownloading 构造已领取下载、尚无下载结果的设备，关闭后返回存储目录。
func setupDownloading(t *testing.T) (*Store, string, CampaignSpec) {
	t.Helper()
	s := setupUpgrade(t, "d1")
	spec := upSpec()
	spec.Devices = []string{"d1"}
	createCampaign(t, s, spec)
	bringOnline(t, s, "d1")
	if _, err := s.Claim(spec.ID, "d1", upBase); err != nil {
		t.Fatalf("claim download: %v", err)
	}
	dir := s.dir
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}
	return s, dir, spec
}

// setupInstalling 构造下载成功、安装已领取但尚无安装结果的设备，
// 返回安装操作标识与关闭后的存储目录。
func setupInstalling(t *testing.T) (*Store, string, CampaignSpec, string) {
	t.Helper()
	s, dir, spec := setupReady(t)
	// setupReady 已关闭存储，重新打开后领取安装。
	s2, err := Open(dir)
	if err != nil {
		t.Fatalf("reopen ready: %v", err)
	}
	in, err := s2.Claim(spec.ID, "d1", upBase.Add(2*time.Minute))
	if err != nil {
		t.Fatalf("claim install: %v", err)
	}
	if in == nil || in.Kind != StageInstall {
		t.Fatalf("want install op, got %+v", in)
	}
	if err := s2.Close(); err != nil {
		t.Fatal(err)
	}
	return s2, dir, spec, in.ID
}

