		At: upBase.Add(5 * time.Minute), Success: true,
		Seq: 2, Version: "v1", Config: json.RawMessage(`{}`),
	}); err != nil {
		t.Fatalf("rollback result: %v", err)
	}
	s.Close()
	return dir, spec
}

